def generate_nifty500_universe():
    base_dir = os.path.dirname(os.path.abspath(__file__))
    project_root = os.path.dirname(base_dir)
    target_path = os.path.join(project_root, "backend", "data", "nifty500_metadata.json")
    
    universe = []
    seen = set()
    
    # Process predefined master universe
    for item in NIFTY500_RAW:
        sym, name, industry, sector, tier, beta, vol, aliases = item
        if sym in seen:
            continue
        seen.add(sym)
        universe.append({
            "symbol": sym,
            "company_name": name,
            "industry": industry,
            "sector": sector,
            "cap_tier": tier,
            "ticker": f"{sym}.NS",
            "baseline_beta": beta,
            "baseline_volatility": vol,
            "keywords": [k.lower() for k in aliases] + [sym.lower(), name.lower(), industry.lower(), sector.lower()]
        })

