    for item in supplemental_tickers:
        sym, name, industry, sector, tier = item
        if sym in seen:
            continue
        seen.add(sym)
        # Calculate realistic baseline beta and vol based on tier and sector
        base_beta = 1.35 if tier == "Small Cap" else (1.15 if tier == "Mid Cap" else 0.95)
        base_vol = 0.35 if tier == "Small Cap" else (0.28 if tier == "Mid Cap" else 0.22)
        universe.append({
            "symbol": sym,
            "company_name": name,
            "industry": industry,
            "sector": sector,
            "cap_tier": tier,
            "ticker": f"{sym}.NS",
            "baseline_beta": base_beta,
            "baseline_volatility": base_vol,
            "keywords": [sym.lower(), name.lower(), industry.lower(), sector.lower()]
        })

    # Sort universe by symbol
    universe.sort(key=lambda x: x["symbol"])

    os.makedirs(os.path.dirname(target_path), exist_ok=True)
    with open(target_path, "w", encoding="utf-8") as f:
        json.dump(universe, f, indent=2, ensure_ascii=False)

    print(f"Generated {len(universe)} verified Indian equities into {target_path}")
    return len(universe)

